 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    starts = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    if not starts:
        return out
    q = deque(starts)
    seen = set(starts)
    h, w = len(grid), len(grid[0])
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == 0:
                seen.add((nr, nc))
                q.append((nr, nc))
                out[nr][nc] = 2
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
