 "content": "def transform(grid):
    out = [row[:] for row in grid]
    height = len(grid)
    width = len(grid[0])

    # The horizontal 8-lines are gates; their missing cells turn into 2.
    gates = [r for r, row in enumerate(grid) if 8 in row]
    holes = {r: [c for c, value in enumerate(grid[r]) if value == 0] for r in gates}
    for r in gates:
        for c in holes[r]:
            out[r][c] = 2

    # Adjacent gates are connected across their open band. The upper gate's
    # holes project downward, while a crossbar spans the lower gate's gaps.
    for upper, lower in zip(gates, gates[1:]):
        for c in holes[upper]:
            for r in range(upper + 1, lower):
                if grid[r][c] == 0:
                    out[r][c] = 2
        cols = holes[upper] + holes[lower]
        if cols and lower - upper > 1:
            bridge = lower - 1
            for c in range(min(cols), min(max(cols) + 1, width)):
                if grid[bridge][c] == 0:
                    out[bridge][c] = 2

    # The marker reaches the first gate: its row above the gate forms the
    # full horizontal bridge; the marker's vertical approach stays aligned.
    marker = next(((r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2), None)
    if marker and gates:
        mr, mc = marker
        first = next((r for r in gates if r > mr), None)
        if first is not None:
            for r in range(mr + 1, first):
                if grid[r][mc] == 0:
                    out[r][mc] = 2
            for c in range(width):
                if grid[first - 1][c] == 0:
                    out[first - 1][c] = 2

    # Openings in the last gate extend downward through the remaining field.
    if gates:
        last = gates[-1]
        for c in holes[last]:
            for r in range(last + 1, height):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out

