 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seed = next(((r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2), None)
    if seed is None:
        return out
    sr, sc = seed

    # Extend the seed's horizontal ray until it meets the first gate's opening.
    bars = [r for r, row in enumerate(grid) if sum(v == 8 for v in row) > w // 2]
    holes = {r: [c for c, v in enumerate(grid[r]) if v == 0] for r in bars}
    if not bars:
        return out

    # Gaps across a striped wall become a horizontal 2-bar; its associated
    # vertical ray is the one selected by the seed and neighboring wall pattern.
    for r in bars:
        for c in holes[r]:
            out[r][c] = 2

    # Observed structure is an open maze: extend color-2 rays from wall gaps
    # only when supported by the seed's line of sight / direct aligned apertures.
    for c in holes[bars[0]]:
        if c == sc:
            for r in range(sr + 1, bars[0]):
                if grid[r][c] == 0:
                    out[r][c] = 2
    # Rows immediately above each wall carry a connector bounded by the gaps
    # visible in that wall and the nearest previously established ray.
    for upper, lower in zip(bars, bars[1:]):
        upper_gaps, lower_gaps = holes[upper], holes[lower]
        if lower - upper == 2:
            for c in set(upper_gaps) | set(lower_gaps):
                if grid[upper + 1][c] == 0:
                    out[upper + 1][c] = 2
        elif lower - upper >= 3:
            for c in upper_gaps:
                if grid[upper + 1][c] == 0:
                    out[upper + 1][c] = 2
            for c in lower_gaps:
                if grid[lower - 1][c] == 0:
                    out[lower - 1][c] = 2

    # Continue the last wall's apertures only where each has an incoming ray.
    last = bars[-1]
    for c in holes[last]:
        if any(out[r][c] == 2 for r in range(last)):
            for r in range(last + 1, h):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out

