        if params[0] and bars:
            # marker vertical ray only until first gate
            for r in range(sr+1,min(bars+[h])):
                if g[r][sc]==0:o[r][sc]=2
        if params[1] and bars and sr<bars[0]:
            # full bridge immediately above first bar
            rr=bars[0]-1
            for c in range(w):
