            if mode==0: cs=set()
            elif mode==1: cs=set(holes[a])
            elif mode==2: cs=set(holes[b])
            elif mode==3: cs=cols
            elif mode==4: cs=set(range(min(cols),max(cols)+1)) if cols else set()
            elif mode==5: cs=set(range(w))
            elif mode==6: cs=set(range(max(0,min(cols)-1),min(w,max(cols)+2))) if cols else set()
            elif mode==7: cs=set(holes[a]) & set(holes[b])
