            for c in range(w):
                if g[rr][c]==0:o[rr][c]=2
    # row filling inside each gap between bars options
    for a,b in zip(bars,bars[1:]):
        for r in range(a+1,b):
            mode=params[2]
            cols=set(holes[a]+holes[b])
            if mode==0: cs=set()
            elif mode==1: cs=set(holes[a])
            elif mode==2: cs=set(holes[b])
            elif mode==3: cs=cols
            elif mode==4: cs=set(range(min(cols),max(cols)+1)) if cols else set()
            elif mode==5: cs=set(range(w))
            elif mode==6: cs=set(range(max(0,min(cols)-1),min(w,max(cols)+2))) if cols else set()
            elif mode==7: cs=set(holes[a]) & set(holes[b])
            elif mode==8: cs=set(holes[a]) ^ set(holes[b])
            # restrict to top/bottom/middle row selection
            if params[3]==1 and r!=a+1:cs=set()
            if params[3]==2 and r!=b-1:cs=set()
            if params[3]==3 and r!=(a+b)//2:cs=set()
            for c in cs:
                if 0<=c<w and g[r][c]==0:o[r][c]=2
    # down from last gate
    if params[4] and bars:
        for c in holes[bars[-1]]:
            for r in range(bars[-1]+1,h):
                if g[r][c]==0:o[r][c]=2
    # direct vertical from any/all gate gaps through blank interval
    if params[5] and len(bars)>1:
        for a,b in zip(bars,bars[1:]):
            for c in holes[a]:
                for r in range(a+1,b):
                    if g[r][c]==0:o[r][c]=2
    return o

